import{_ as l,l as n,o as r,c as i,v as e,p as s,x as t,d as p,i as u,S as d}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"Parlour 限价簿排队","description":"","frontmatter":{"title":"Parlour 限价簿排队","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/parlour-lob.md","filePath":"quant/parlour-lob.md","lastUpdated":1789023840000}'),E={name:"quant/parlour-lob.md"};function h(c,a,B,m,_,f){const o=n("Mermaid");return r(),i("div",null,[a[1]||(a[1]=e('<h1 id="parlour-限价簿排队" tabindex="-1">Parlour 限价簿排队 <a class="header-anchor" href="#parlour-限价簿排队" aria-label="Permalink to &quot;Parlour 限价簿排队&quot;">​</a></h1><div class="epigraph"><p>限价单的价值取决于你前面排了多少人、对面簿有多厚。同一笔意向，在队尾可能变成市价单，在队空时才值得挂着等。</p><footer>—— Parlour, Price Dynamics in Limit Order Markets, Review of Financial Studies, 1998</footer></div><p><a href="/quant/transparency-anonymity">透明度</a>停在信息集：谁看见深度与身份。主干已有<a href="/quant/lob-structure">LOB 几何</a>与<a href="/quant/order-types">订单类型</a>，本课不重画价位阶梯，也不重推 Kyle 的 \\(\\lambda\\)。缺口是第一张<strong>策略性限价簿</strong>：交易者在市价与限价之间选择，限价单进入队列，执行概率依赖两侧深度。Parlour（1998）用两档、序贯到达，把排队写成马尔可夫博弈。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>报价驱动模型里，专家或做市商外生存在，客户只提交市价。电子簿上每个人都可以挂限价，流动性供给是进入队列的决策。若己方队列已长，新来的限价单执行概率低，不如吃掉对方；若己方队列空、对方厚，挂单等待更划算。价格动态来自深度状态的转移，而不是外生的 \\(V\\) 跳跃。问题是：在极简的两档簿上，能否存在均衡的下单规则，使观察到的价差与深度有持续性。</p><p>这与 Ho–Stoll 不同：没有一个指定经销商的库存状态，状态是<strong>两侧队列长度</strong>。库存被分散到排队的限价单里。</p><h3 id="为什么必须先排队、后竞争" tabindex="-1">为什么必须先排队、后竞争 <a class="header-anchor" href="#为什么必须先排队、后竞争" aria-label="Permalink to &quot;为什么必须先排队、后竞争&quot;">​</a></h3><p>若忽略队列，限价单像一张免费的美式期权，人人挂在最优价，簿无限厚。时间优先让位置成为稀缺：先到的人拥有更高的成交权。Parlour 把这一点做成序贯博弈的核心，Foucault 下一课再加入被捡便宜（picking-off）的等待成本。本课先让执行概率随队深下降。</p><p><span class="marginnote">真实簿有多档、隐藏单、pro-rata。Parlour 的两档是为了让马尔可夫状态可写。结论的定性——己方厚则更可能吃市价——在多档上仍然是一阶直觉。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>离散时间，每期来一个交易者，方向随机或带估值。簿上各只有一个价位的买卖队列（长度为状态）。行动：市价买、市价卖、限价买、限价卖、或不交易。市价立刻与对方队头成交；限价加到己方队尾。价值过程可以是公开随机游走，使「等」有机会成本。均衡是状态依赖的策略：在每个队列对 \\((n_b,n_a)\\) 上给出行动概率。</p><p>比较静态：己方队列增加，限价的执行概率下降，市价概率上升。于是深度有均值回复：太厚的一侧会少人再挂、多人来吃。价格（由哪一侧被吃）因此也有条件动态。</p><h3 id="与-glosten-电子簿的预告" tabindex="-1">与 Glosten 电子簿的预告 <a class="header-anchor" href="#与-glosten-电子簿的预告" aria-label="Permalink to &quot;与 Glosten 电子簿的预告&quot;">​</a></h3><p>Glosten（1994）把整张簿写成竞争性限价供给曲线，逆向选择决定各档深度。Parlour 几乎没有逆向选择，主引擎是执行概率与时间优先。两篇合在一起才是后文单元：排队摩擦 × 信息。本课先隔离排队。</p>',14)),(r(),s(d,null,{default:t(()=>[u(o,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20St%5B%22%E7%8A%B6%E6%80%81%3A%20%E4%B9%B0%E9%98%9F%E5%88%97%20nb%2C%20%E5%8D%96%E9%98%9F%E5%88%97%20na%22%5D%20--%3E%20Ch%5B%22%E5%B8%82%E4%BB%B7%E6%88%96%E9%99%90%E4%BB%B7%22%5D%0A%20%20Ch%20--%3E%7C%22%E5%B7%B1%E6%96%B9%E5%B7%B2%E5%8E%9A%22%7C%20MKT%5B%22%E6%9B%B4%E5%8F%AF%E8%83%BD%E5%B8%82%E4%BB%B7%E5%90%83%E5%AF%B9%E9%9D%A2%22%5D%0A%20%20Ch%20--%3E%7C%22%E5%B7%B1%E6%96%B9%E8%96%84%E3%80%81%E5%AF%B9%E9%9D%A2%E5%8E%9A%22%7C%20LMT%5B%22%E6%9B%B4%E5%8F%AF%E8%83%BD%E9%99%90%E4%BB%B7%E6%8E%92%E9%98%9F%22%5D%0A%20%20MKT%20--%3E%20St%0A%20%20LMT%20--%3E%20St%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>时间优先把流动性供给变成占位。占到队头的人出售即时性，与 Grossman–Miller 的「在场」同构，但在场被实现为队列名次。名次靠后的限价单其实是一份很差的期权：价格走了还没轮到。理性交易者不会在队尾无限堆积，深度因而内生有限——即使没有逆向选择。这纠正「电子簿会自动无限深」的幻觉。</p><p>价格持续性来自状态持续性：一侧被吃薄之后，下一期更可能有人在那一侧补限价，而不是继续同方向市价。于是短期价格有反转成分，来源是簿的补给，不是 Roll 弹跳。VR 在这种市场上会小于 1，即使没有买卖价差弹跳的会计。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>两档、单位订单、无撤单，是硬边界。真实交易者可以撤单重挂抢队，排队价值被侵蚀，见后文撤单博弈。知情交易者会让「吃薄的一侧」变成信息而非补给信号，反转被削弱甚至反转成动量。tick 大小改变有几档可挂，两档模型不能谈最优放置。</p><p><span class="marginnote">不要用 Parlour 去校准 Level-2 的十档形状。它解释的是下单类型对队列状态的条件概率，不是幂律深度。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Parlour（1998）把限价簿写成队列状态上的序贯博弈：己方厚则改吃市价，深度因此均值回复。</li><li>时间优先使位置稀缺，即使无逆向选择，深度也有限。</li><li>簿补给可制造短期价格反转，对象不是专家库存。</li><li>不重画 LOB 几何；多档、隐藏、信息留给后续课。</li><li>出处：Parlour, <em>Review of Financial Studies</em>, 1998；几何先修见 Harris 与本站限价簿课。</li></ul>',8))])}const q=l(E,[["render",h]]);export{b as __pageData,q as default};
